def decode(encoded, original, message):
    # Step 1: Build a mapping from encoded letters to their original letters
    mapping = {}
    for i, char in enumerate(original):
        mapping[char] = encoded[i]

    # Step 2: Use the mapping to decode the encrypted message
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

