    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    """

    # Initialize a table to store the dynamic programming results
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Base case: if the box capacity is 0, there is no remaining space
    for i in range(n + 1):
        dp[0][i] = 0

    # Loop through the items and their volumes
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # Case 1: the current item fits in the current box capacity
            if volumes[j - 1] <= i:
                dp[i][j] = min(dp[i][j], dp[i - volumes[j - 1]][j - 1])

            # Case 2: the current item does not fit in the current box capacity
            dp[i][j] = min(dp[i][j], dp[i][j - 1] + volumes[j - 1])

    # Return the difference between the box capacity and the maximum occupied volume
    return V - max(dp[V])

