        decrypted_text += decrypted_char
    return decrypted_text

def next_permutation(perm):
    if len(perm) == 1:
        return False

    for i in range(len(perm) - 1, 0, -1):
        if perm[i] > perm[i - 1]:
            break

    if i == 0:
        return False

    # Swap the smallest number larger than perm[i - 1] with perm[i - 1]
    smallest = next(x for x in perm[i:] if x > perm[i - 1])
    perm[i - 1], smallest = smallest, perm[i - 1]

    # Reverse the order of numbers after i - 1
    perm[i:] = perm[i:][::-1]

    return True

def total_smoked_cigarettes(n, k):

    if n < 0 or k < 0:
        raise ValueError("n and k must be positive integers.")

    total = n
    while n >= k:
        total += n // k
        n = n // k

    return total
